        mute_2:"<span><i class='fa fa-bullseye' aria-hidden='true' ></i></span>&nbsp;\u09AA\u09A6\u0995\u09CD\u09B7\u09C7\u09AA \u09E8: \u09AE\u09BF\u0989\u099F\u09C7\u09B6\u09A8 \u098F\u09B0 \u099C\u09A8\u09CD\u09AF \u09AB\u09C0 \u09A6\u09BF\u09A4\u09C7 \u0997\u09C7\u09B2\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0986\u09AC\u09C7\u09A6\u09A8 -> \u09AB\u09BF \u0986\u09A6\u09BE\u09DF \u09AE\u09C7\u09A8\u09C1 \u09A4\u09C7 \u09AF\u09BE\u09A8, \u0993\u0996\u09BE\u09A8\u09C7 \u09B0\u09BF\u0995\u09CB\u09DF\u09C7\u09B8\u09CD\u099F \u098F\u09B0 \u09A7\u09B0\u09A8, \u098F\u09AA\u09CD\u09B2\u09BF\u0995\u09C7\u09B6\u09A8 \u09A8\u09BE\u09AE\u09CD\u09AC\u09BE\u09B0 \u09A6\u09BF\u09DF\u09C7 \u09B8\u0982\u09AF\u09CB\u099C\u09A8 \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u09A4\u09BE\u09B0\u09AA\u09B0 \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09A7\u09BE\u09AA \u0997\u09C1\u09B2\u09CB \u09B8\u09AE\u09CD\u09AA\u09C2\u09B0\u09CD\u09A3 \u0995\u09B0\u09C1\u09A8\u0964 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09AE\u09CB\u09A1 \u098F  (\u09A8\u09C7\u099F\u09AC\u09CD\u09AF\u09BE\u0982\u0995\u09BF\u0982 \u098F\u09A8\u09CD\u09A1 \u09A1\u09C7\u09AC\u09BF\u099F \u0995\u09BE\u09B0\u09CD\u09A1 \u0985\u09AA\u09B8\u09A8 \u0985\u09AB \u0997\u09CD\u09B0\u09BF\u09AA\u09CD\u09B8\u09CD) \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u0995\u09B0\u09C7\u09A8 \u09A4\u09BE\u09B9\u09B2\u09C7 \u09AE\u09BF\u0989\u099F\u09C7\u09B8\u09BE\u09A8 \u0995\u09C7\u09B8 \u09B8\u09BE\u09A5\u09C7 \u09B8\u09BE\u09A5\u09C7 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0 \u09B9\u09DF\u09C7 \u09AF\u09BE\u09AC\u09C7\u0964 \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u0997\u09CD\u09B0\u09BF\u09AA\u09CD\u09B8 \u098F\u09B0  \u0995\u09BE\u0989\u09A8\u09CD\u099F\u09BE\u09B0 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F  \u0985\u09AA\u09B8\u09A8 \u09A6\u09BF\u09DF\u09C7 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u0995\u09B0\u09C7\u09A8 \u09A4\u09BE\u09B9\u09B2\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0986\u09AC\u09C7\u09A6\u09A8 -> \u098F\u09AA\u09CD\u09B2\u09BF\u0995\u09C7\u09B6\u09A8 \u099C\u09BF \u0986\u09B0 \u098F\u09A8 \u0985\u09A8\u09C1\u09B8\u09A8\u09CD\u09A7\u09BE\u09A8 \u09AE\u09C7\u09A8\u09C1 \u09A6\u09BF\u09DF\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u0995\u09C7 \u09AF\u09BE\u099A\u09BE\u0987 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u0995\u09C7\u09B8 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0 \u0995\u09B0\u09BE\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964 \u098F\u099B\u09BE\u09B0\u09BE\u0993, \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09AE\u09CB\u09A1 \u098F  \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F  \u0995\u09B0\u09BE\u09B0 \u09AA\u09B0 \u0993 \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09C7\u09B8 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0 \u09A8\u09BE \u09B9\u09DF \u09A4\u09BE\u09B9\u09B2\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0986\u09AC\u09C7\u09A6\u09A8 -> \u098F\u09AA\u09CD\u09B2\u09BF\u0995\u09C7\u09B6\u09A8 \u099C\u09BF \u0986\u09B0 \u098F\u09A8 \u0985\u09A8\u09C1\u09B8\u09A8\u09CD\u09A7\u09BE\u09A8 \u09AE\u09C7\u09A8\u09C1 \u09A6\u09BF\u09DF\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u0995\u09C7 \u09AF\u09BE\u099A\u09BE\u0987 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u0995\u09C7\u09B8 \u09B0\u09C7\u099C\u09BF\u09B8\u09CD\u099F\u09BE\u09B0 \u0995\u09B0\u09BE\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964",		
        conv_help:"\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u099C\u09AE\u09BF\u09B0 \u09B6\u09CD\u09B0\u09C7\u09A3\u09C0 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8\u09C7\u09B0 \u0986\u09AC\u09C7\u09A6\u09A8 \u09AA\u09CD\u09B0\u0995\u09CD\u09B0\u09BF\u09AF\u09BC\u09BE",
        conv_1:'<span><i class="fa fa-bullseye" aria-hidden="true" ></i></span>&nbsp;\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u098F \u099C\u09AE\u09BF\u09B0 \u09B6\u09CD\u09B0\u09C7\u09A3\u09C0 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8\u09C7\u09B0 \u098F\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09AC\u09C7\u09A6\u09A8 \u0995\u09B0\u09A4\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0986\u09AC\u09C7\u09A6\u09A8 -> \u099C\u09AE\u09BF\u09B0 \u09B6\u09CD\u09B0\u09C7\u09A3\u09C0 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09A8\u09C7\u09B0 \u0986\u09AC\u09C7\u09A6\u09A8 \u09AE\u09C7\u09A8\u09C1 \u09A4\u09C7 \u09AF\u09BE\u09A8 \u098F\u09AC\u0982 \u098F\u09B0 \u09AA\u09B0 \u09AE\u09BF\u0989\u099F\u09C7\u09B6\u09A8 \u098F\u09B0 \u09AE\u09A4\u09CB \u09B8\u09AE\u09B8\u09CD\u09A4 \u09AA\u09A6\u0995\u09CD\u09B7\u09C7\u09AA \u098F\u0995 \u0987 \u09AD\u09BE\u09AC\u09C7 \u09B8\u09AE\u09CD\u09AA\u09A8\u09CD\u09A8 \u0995\u09B0\u09C1\u09A8 \u0964 ',
        ror_help:'\u0986\u09B0 \u0993  \u0986\u09B0 / \u09AA\u09CD\u09B2\u099F \u09A4\u09A5\u09CD\u09AF / \u09AA\u09CD\u09B2\u099F \u09AE\u09BE\u09A8\u099A\u09BF\u09A4\u09CD\u09B0\u09C7\u09B0 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09AF\u09BC\u09BF\u09A4 \u0995\u09AA\u09BF\u09B0 \u099C\u09A8\u09CD\u09AF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0985\u09A8\u09C1\u09B0\u09CB\u09A7 - \u09AA\u09CD\u09B0\u0995\u09CD\u09B0\u09BF\u09AF\u09BC\u09BE',
